#include <iostream>
#include <array>
template<size_t N>
constexpr size_t factorial(size_t n) {
  return n == 0 ? 1 : n * factorial<N>(n - 1);
}
int main() {
  constexpr size_t fact_5 = factorial<5>(5); // Compile-time computation
  static_assert(fact_5 == 120, "Factorial calculation incorrect");
  std::array<int, fact_5> arr; // Array size determined at compile time
  std::cout << arr.size() << std::endl;
  return 0;
}
